"""Section 7: Proposition 19 is sharp at five copies.  The qutrit five-qudit code [[5,1,3]]_3 (stabilizer generated by the
cyclic shifts of X Z Z^{-1} X^{-1} I) has a three-dimensional code space; every two-dimensional subspace V of it has
balanced range (in fact maximally mixed two-copy marginals) and q_5(Pi_V) = 5/8, the bound of Proposition 19.
Also checks the enumerator formula for subspaces of stabilizer codes against direct partial traces, on random
[[5,1]]_3 codes, at t = 1/2 and 2/5:
    q_N(t, P_code - |c><c|) = (4/3^N) [ W_S + W_l/2 ],  W_X = sum_{E in X} (1 - 3t)^{N - wt E},
for c a logical eigenstate of the logical class l (W_S over the stabilizer group, W_l over the coset l + S).
usage: python perfect_code_check.py"""
import itertools
import numpy as np

N = 5
om = np.exp(2j * np.pi / 3)
Xm = np.roll(np.eye(3), 1, axis=0)
Zm = np.diag([1, om, om ** 2])
rng = np.random.default_rng(0)


def pauli(vec):
    M = np.array([[1.0 + 0j]])
    for i in range(N):
        M = np.kron(M, np.linalg.matrix_power(Xm, int(vec[i])) @ np.linalg.matrix_power(Zm, int(vec[N + i])))
    return M


def q_direct(C, t):
    tot = 0.0
    for r in range(N + 1):
        for K in itertools.combinations(range(N), r):
            Xr, rem = C.reshape([3] * 2 * N), list(range(N))
            for s in sorted(K, reverse=True):
                i = rem.index(s); Xr = np.trace(Xr, axis1=i, axis2=len(rem) + i); rem.pop(i)
            tot += (-t) ** r * np.sum(np.abs(Xr) ** 2)
    return tot


def sympl(u, v):
    return (u[:N] @ v[N:] - u[N:] @ v[:N]) % 3


def span(gens):
    pts = np.zeros((1, 2 * N), dtype=np.int64)
    for g in gens:
        pts = np.concatenate([(pts + k * g) % 3 for k in range(3)])
    return pts


def weights(P):
    return ((P[:, :N] != 0) | (P[:, N:] != 0)).sum(1)


def code_projector(S):
    PC = np.eye(3 ** N, dtype=complex)
    for g in S:
        G = pauli(g)
        PC = PC @ (np.eye(3 ** N) + G + G @ G) / 3
    return PC


ok = True
# the perfect code
pat = [(1, 0), (0, 1), (0, 2), (2, 0), (0, 0)]
S = np.array([[pat[(k - s) % 5][0] for k in range(N)] + [pat[(k - s) % 5][1] for k in range(N)] for s in range(4)])
assert all(sympl(a, b) == 0 for a in S for b in S)
PC = code_projector(S)
w, V = np.linalg.eigh((PC + PC.conj().T) / 2)
code = V[:, w > 0.5]
vals, devs = [], []
for trial in range(5):
    U = np.linalg.qr(rng.normal(size=(3, 2)) + 1j * rng.normal(size=(3, 2)))[0]
    B = code @ U
    Pi = B @ B.conj().T
    vals.append(q_direct(Pi, 0.5))
    Vt = B.reshape([3] * N + [2])
    for k in (1, 2):
        for Sset in itertools.combinations(range(N), k):
            Mm = np.moveaxis(Vt, list(Sset), list(range(k))).reshape(3 ** k, -1)
            devs.append(np.abs(Mm @ Mm.conj().T / 2 - np.eye(3 ** k) / 3 ** k).max())
good = code.shape[1] == 3 and max(abs(v - 5 / 8) for v in vals) < 1e-12 and max(devs) < 1e-12
ok &= good
print(f"perfect code: dimension {code.shape[1]}; q_5(1/2) on five random 2-dim subspaces: {[round(v, 12) for v in vals]} (5/8); "
      f"max deviation of one- and two-copy marginals from maximally mixed {max(devs):.1e}: {good}")


# the enumerator formula on random codes
def transvect(M, v):
    coef = (M[:, :N] @ v[N:] - M[:, N:] @ v[:N]) % 3
    return (M + np.outer(coef, v)) % 3


worst = 0.0
for trial in range(4):
    M = np.zeros((N + 1, 2 * N), dtype=np.int64)
    for i in range(N - 1):
        M[i, N + i] = 1
    M[N - 1, N - 1] = 1
    M[N, 2 * N - 1] = 1
    for _ in range(12 * N):
        M = transvect(M, rng.integers(0, 3, size=2 * N))
    Sg, LX, LZ = M[:N - 1], M[N - 1], M[N]
    Sp = span(Sg)
    PC = code_projector(Sg)
    for Lv in (LZ, LX, (LX + LZ) % 3):
        Lop = pauli(Lv)
        Proj = PC @ (np.eye(3 ** N) + Lop + Lop @ Lop) / 3
        ww, VV = np.linalg.eigh((Proj + Proj.conj().T) / 2)
        c = VV[:, -1]
        Pi = PC - np.outer(c, c.conj())
        for t in (0.5, 0.4):
            lam = 1 - 3 * t
            formula = 4 / 3 ** N * (np.sum(lam ** (N - weights(Sp))) + 0.5 * np.sum(lam ** (N - weights((Sp + Lv) % 3))))
            worst = max(worst, abs(q_direct(Pi, t) - formula))
ok &= worst < 1e-10
print(f"enumerator formula for code subspaces vs direct partial traces (4 random codes, 3 logical classes, t = 1/2, 2/5): "
      f"max error {worst:.1e}")
print("PASS" if ok else "FAIL")
